def seal_area(heights):
    stack = []
    best = 0
    for right in range(len(heights) + 1):
        height = 0
        if right < len(heights):
            height = heights[right]
        left = right
        while len(stack) > 0 and stack[-1][1] >= height:
            item = stack.pop()
            left = item[0]
            area = (right - left) * item[1]
            if area > best:
                best = area
        stack.append([left, height])
    return best

